      "locale": locale,
      "currency": currency,
  };
}

final class TopupRequest {
  final String cardId;
  final int amountCentavos;
  final String? note;
  final String? idempotencyKey;

  const TopupRequest({
    required this.cardId,
    required this.amountCentavos,
    this.note,
    this.idempotencyKey,
  });

  factory TopupRequest.fromJson(Map<String, Object?> json) => TopupRequest(
      cardId: json["cardId"] as String,
      amountCentavos: (json["amountCentavos"] as num).toInt(),
      note: json["note"] == null ? null : json["note"] as String,
      idempotencyKey: json["idempotencyKey"] == null ? null : json["idempotencyKey"] as String,
  );

  Map<String, Object?> toJson() => {
      "cardId": cardId,
      "amountCentavos": amountCentavos,
      "note": note,
      "idempotencyKey": idempotencyKey,
  };
}
